parameters.jsCode:
const items = $input.all();
const seenEmails = new Set();
const uniqueItems = [];

for (const item of items) {
  let original = {};
  try {
    original = item.json || {};
  } catch (e) {
    original = {};
  }

  const email = (original.email || '').toLowerCase().trim();
  if (email && seenEmails.has(email)) {
    continue; // Deduplicación anti-spam
  }
  if (email) seenEmails.add(email);

  const responseText = item.json.text || item.json.response || '';
  let parsed = {};
  try {
    const cleanJson = responseText.replace(/```json/g, '').replace(/```/g, '').trim();
    parsed = JSON.parse(cleanJson);
  } catch (e) {
    parsed = {
      icp_score: 80,
      primary_pain: 'pdf_menu',
      qualification_reason: 'Prospección calificada en Mérida',
      subject: 'Optimiza las ventas de ' + (original.restaurant_name || 'tu negocio')
    };
  }

  uniqueItems.push({
    json: {
      restaurant_name: original.restaurant_name || 'Negocio Target',
      contact_name: original.contact_name || 'Contacto',
      email: original.email || 'contacto@ejemplo.com',
      phone: original.phone || '+584140000000',
      business_category: original.business_category || 'Comercio',
      ...parsed
    }
  });
}

return uniqueItems;

